import{_ as n,o as s,c as e,a2 as t}from"./chunks/framework.BOeh4kYD.js";const u=JSON.parse('{"title":"关于数字员工工场","description":"","frontmatter":{},"headers":[],"relativePath":"zh/about.md","filePath":"zh/about.md","lastUpdated":1790745464000}'),l={name:"zh/about.md"};function i(o,a,r,p,c,h){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="关于数字员工工场" tabindex="-1">关于数字员工工场 <a class="header-anchor" href="#关于数字员工工场" aria-label="Permalink to &quot;关于数字员工工场&quot;">​</a></h1><p>数字员工工场由朱卫（joinwell52-AI）独立维护。工场持续生产可核验的数字员工工作成果，并公开研究方法、运行规范、工作记录、观察笔记和正式出版物。</p><h2 id="当前数字研究员" tabindex="-1">当前数字研究员 <a class="header-anchor" href="#当前数字研究员" aria-label="Permalink to &quot;当前数字研究员&quot;">​</a></h2><p>当前能力版本是：</p><ul><li><strong>研究报告生产机 V1.3</strong>；</li><li><strong>Research Runtime Center V4</strong>；</li><li><strong>Research Runtime Scheduler V2.0</strong>；</li><li><strong>Research Skills V2.0</strong>；</li><li><strong>Research Intelligence System V1.0</strong>。</li></ul><p>研究报告生产机是一个通过 ChatGPT 实现的 Research Analyst 数字员工。它使用三条情报管线为三个长期栏目发现信号、筛选选题、推进研究、生产完整中英文报告，并通过 GitHub First 完成正式发版与验证。</p><h2 id="产品与工程层级" tabindex="-1">产品与工程层级 <a class="header-anchor" href="#产品与工程层级" aria-label="Permalink to &quot;产品与工程层级&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA + FCoP</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>CodeFlowMu + Digital Employee</span></span></code></pre></div><ul><li><strong>TMPA：</strong> 独立理论与规范层；</li><li><strong>FCoP：</strong> 基于文件的协同协议；</li><li><strong>CodeFlowMu：</strong> 数字员工开发与工作 Runtime；</li><li><strong>Digital Employee：</strong> 产品与交付层。</li></ul><p>网站能力区按这个层级展示：TMPA 与 FCoP 在第一排，CodeFlowMu 位于第二排首位，随后是 Digital Employee。</p><p><strong>FCoP 4.0.5</strong> 提供 MIT 开源 Python 库和可选的 Canonical MCP 适配器：<strong>25 个工具、6 个资源，无资源模板</strong>。Core 负责协议事实、验证和状态迁移；MCP 是 Core 的薄适配器。Runtime、Profile 预设、Host 配置和 Legacy 兼容均在 Base Protocol 之外。<a href="https://doi.org/10.5281/zenodo.23051275" target="_blank" rel="noreferrer">软件归档</a> · <a href="https://doi.org/10.5281/zenodo.22855630" target="_blank" rel="noreferrer">FCoP 预印本 1.0</a> · <a href="https://github.com/joinwell52-AI/FCoP/blob/main/CITATION.cff" target="_blank" rel="noreferrer">FCoP 引用元数据</a>。论文实验与补充材料使用冻结的 4.0.3 实现；4.0.5 软件更新不代表这些实验已重新运行。</p><h2 id="三个研究栏目" tabindex="-1">三个研究栏目 <a class="header-anchor" href="#三个研究栏目" aria-label="Permalink to &quot;三个研究栏目&quot;">​</a></h2><ul><li><strong>数字员工：</strong> 岗位、职责、工作流、运行、治理与评估；</li><li><strong>行业架构：</strong> OpenAI、Claude、Gemini、Cursor、GitHub Copilot、Microsoft Copilot Platform 等主要 AI 平台的产品和运行架构；</li><li><strong>开源工程：</strong> Agent Runtime、协议、SDK、工具、Benchmark、恢复与可观测性工程。</li></ul><h2 id="三条研究情报管线" tabindex="-1">三条研究情报管线 <a class="header-anchor" href="#三条研究情报管线" aria-label="Permalink to &quot;三条研究情报管线&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI 平台变更情报</span></span>
<span class="line"><span>GitHub 工程情报</span></span>
<span class="line"><span>论文与研究成果情报</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>统一信号池与去重</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>三个栏目分别选题</span></span></code></pre></div><h2 id="研究方法" tabindex="-1">研究方法 <a class="header-anchor" href="#研究方法" aria-label="Permalink to &quot;研究方法&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>真实来源与工程</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>可重建证据</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>受治理研究生命周期</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>完整报告生产</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>GitHub 与网站发版</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>架构、规范与公开出版</span></span></code></pre></div><p>观察笔记记录数字员工在工作中看到的学术、平台与开源动态，不自动构成 TMPA 论文证据。</p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><ul><li><a href="./publications/research-report-production-engine-v1.3">研究报告生产机 V1.3</a></li><li><a href="./publications/research-report-production-engine-v1.3-quickstart">V1.3 快速开始</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/archive/refs/heads/main.zip" target="_blank" rel="noreferrer">下载当前源码 ZIP</a></li></ul>`,20)])])}const g=n(l,[["render",i]]);export{u as __pageData,g as default};
